export function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const end = s.slice(2).search(/[/?#]/)
    const stop = end < 0 ? s.length : end + 2
    r.authority = s.slice(2, stop)
    s = s.slice(stop)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

export function splitAuthority(a) {
  let userinfo
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const rb = a.lastIndexOf(']')
  const colon = a.indexOf(':', rb + 1)
  let host = a, port
  if (colon >= 0) { host = a.slice(0, colon); port = a.slice(colon + 1) }
  return { userinfo, host, port }
}

export function removeDots(path) {
  let inp = path, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

export class UriError extends Error {}

const truncated = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)

export function normalize(r) {
  let userinfo, host, port
  if (r.authority !== undefined) ({ userinfo, host, port } = splitAuthority(r.authority))
  const checks = [['path', r.path], ['userinfo', userinfo], ['host', host], ['query', r.query], ['fragment', r.fragment]]
  for (const [name, v] of checks) {
    if (v !== undefined && truncated(v)) throw new UriError(`the ${name} has a truncated percent-encoding`)
  }
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let path = removeDots(pct(r.path))
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (r.authority !== undefined) {
    if (port === '' || (port !== undefined && DEFAULT[scheme] === port)) port = undefined
    out += '//'
    if (userinfo !== undefined) out += pct(userinfo) + '@'
    out += lower(pct(host))
    if (port !== undefined) out += ':' + port
    if (path === '') path = '/'
  }
  out += path
  if (r.query !== undefined) out += '?' + pct(r.query)
  if (r.fragment !== undefined) out += '#' + pct(r.fragment)
  return out
}

export function resolve(base, ref) {
  const t = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: ref.fragment }
  if (ref.scheme !== undefined) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
